enum MemorySensitivity { ordinary, sensitive, secret }
enum MemoryDecision { allow, requireConsent, reject }
class MemoryProposal { const MemoryProposal({required this.key, required this.sensitivity, required this.consented, this.expiresAt, this.forgetRequested = false}); final String key; final MemorySensitivity sensitivity; final bool consented, forgetRequested; final DateTime? expiresAt; }
class MemoryPolicyResult { const MemoryPolicyResult(this.decision, this.reason); final MemoryDecision decision; final String reason; }
class PersonalAiMemoryPolicy { const PersonalAiMemoryPolicy(); MemoryPolicyResult evaluate(MemoryProposal p, DateTime now) { if (p.key.trim().isEmpty || p.forgetRequested) return const MemoryPolicyResult(MemoryDecision.reject, 'Empty key or forget requested'); if (p.expiresAt != null && !p.expiresAt!.isAfter(now)) return const MemoryPolicyResult(MemoryDecision.reject, 'Expired'); if (p.sensitivity == MemorySensitivity.secret) return const MemoryPolicyResult(MemoryDecision.reject, 'Secrets cannot be retained'); if (!p.consented) return const MemoryPolicyResult(MemoryDecision.requireConsent, 'Memory is opt-in'); return const MemoryPolicyResult(MemoryDecision.allow, 'Consent and retention checks passed'); } }
